// Conformance tables for mv-numfmt's to_fixed / to_precision.
//
// Usage: node gen_vectors.mjs
// Writes to_fixed.txt and to_precision.txt beside this script.
//
// Every row is `<input> <digits> <want>`: the decimal input (parsed with
// correct rounding on both sides, so both read the same double; `-0`,
// `NaN`, `Infinity`, `-Infinity` are specials), the digit count, and the
// exact string Node's own method returns. The Rust test reads both files
// with `include_str!` and asserts every row.

import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const dir = dirname(fileURLToPath(import.meta.url));

// Deterministic PRNG so regeneration is stable.
function mulberry32(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rand = mulberry32(0x2f6e2b1);

function encodeInput(x) {
  if (Number.isNaN(x)) return "NaN";
  if (x === Infinity) return "Infinity";
  if (x === -Infinity) return "-Infinity";
  if (Object.is(x, -0)) return "-0";
  return String(x);
}

// Values the vitest tests and the call sites use, plus every edge the port
// tripped on: decimal ties (2.675), exact binary ties (0.125, 2.5), -0,
// the 1e21 fallback boundary, subnormals, infinities.
const handpicked = [
  0, -0, 1, -1, 0.5, -0.5, 1.5, -1.5, 2.5, -2.5, 3.5,
  0.125, -0.125, 0.375, 0.0625, 0.03125, 2.125, 3.375, 6.3,
  2.675, -2.675, 1.005, -1.005, 1.0005, -1.0005, 0.045, 0.055, 0.065, 0.025,
  0.1, 0.2, 0.3, 0.1 + 0.2, 0.30000000000000004, 2.0 * 0.1, 3.0 * 0.2,
  1.035, 1.03511, 1.04, 1.25, 0.9, 0.99, 99.6, 99.99, 999.9, 999.99,
  9999.99, 9.999, 99999.99, 99999.996, 123456, 1234567, 27000, 250000,
  1.23e-7, -1.23e-7, 1e-7, 1e-6, 1e-5, 1e-4, 0.00001, -0.00001, 0.00004,
  0.00005, 0.0005, -0.0004, -0.0005, -0.0016, -0.5, -2.5, -2.5e-7, 2e-6, -3e-5,
  0.001, 0.0016, 0.01, 0.06, 0.066, 0.25, 0.6, 0.66, 1.2325, 1.2345,
  Math.sin(3.14), 5.5, 4.0, 5.0, 7.0, 2.0, 3.0, 2.25, 80.0,
  Math.exp(0.5), 2 * Math.exp(0.1), 1.6487212707, 2.21034,
  5e-324, 4.9e-324, 2.5e-324, 2e-324, 1e-323, 1e-320, 1e-310,
  2.2250738585072014e-308, 1e308, 1.7976931348623157e308,
  1e21, -1e21, 1.5e21, -1.5e21, 2e21, 6.02e23, 1e22,
  123456789012345680000, 1e21 - 131072, 1e21 - 65536, 1e21 + 131072,
  9.999999999999998e20, 999999999999999900000,
  NaN, Infinity, -Infinity,
];

const pool = [...handpicked];

// Magnitude sweep: uniform decimal exponents across the whole double range.
for (let i = 0; i < 1500; i++) {
  const e = Math.floor(rand() * 632) - 324;
  const mantissa = 1 + rand() * 9;
  const sign = rand() < 0.5 ? -1 : 1;
  pool.push(sign * mantissa * 10 ** e);
}
// Near-zero cluster, reaching into the subnormals.
for (let i = 0; i < 200; i++) {
  const scale = [1e-320, 1e-310, 1e-300][i % 3];
  pool.push((rand() * 2 - 1) * rand() * scale);
}
// The 1e21 fallback boundary on both sides.
for (let i = 0; i < 200; i++) {
  pool.push(1e21 * (1 + (rand() - 0.5) * 2e-9) * (rand() < 0.5 ? -1 : 1));
}
// Exact binary ties: odd multiples of 2^-n, ties at some digit count.
for (let i = 0; i < 200; i++) {
  const n = 1 + Math.floor(rand() * 9);
  const j = Math.floor(rand() * 2000) - 1000;
  pool.push((2 * j + 1) / 2 ** n);
}
// Small integers with dyadic fractions, as URL values read.
for (let i = 0; i < 100; i++) {
  pool.push(Math.floor(rand() * 200 - 100) + [0, 0.5, 0.25, 0.75][i % 4]);
}

function rowsFixed() {
  const rows = [];
  for (const x of handpicked) {
    for (let f = 0; f <= 6; f++) rows.push([x, f, x.toFixed(f)]);
  }
  for (const x of pool.slice(handpicked.length)) {
    const f = Math.floor(rand() * 7);
    rows.push([x, f, x.toFixed(f)]);
  }
  // Wider digit counts on a sample, up to the spec's 100.
  for (let i = 0; i < handpicked.length; i += 2) {
    for (const f of [7, 12, 20, 100]) rows.push([handpicked[i], f, handpicked[i].toFixed(f)]);
  }
  return rows;
}

function rowsPrecision() {
  const rows = [];
  for (const x of handpicked) {
    for (let p = 1; p <= 6; p++) rows.push([x, p, x.toPrecision(p)]);
  }
  for (const x of pool.slice(handpicked.length)) {
    const p = 1 + Math.floor(rand() * 6);
    rows.push([x, p, x.toPrecision(p)]);
  }
  for (let i = 0; i < handpicked.length; i += 2) {
    for (const p of [7, 12, 17, 21, 100]) rows.push([handpicked[i], p, handpicked[i].toPrecision(p)]);
  }
  return rows;
}

function write(name, rows) {
  const lines = [
    `# ${name}: <input> <digits> <want>, generated by gen_vectors.mjs`,
    `# node ${process.version}, ${rows.length} rows`,
    ...rows.map(([x, d, want]) => `${encodeInput(x)} ${d} ${want}`),
  ];
  writeFileSync(join(dir, name), lines.join("\n") + "\n");
}

const fixed = rowsFixed();
const precision = rowsPrecision();
write("to_fixed.txt", fixed);
write("to_precision.txt", precision);
console.log(`to_fixed: ${fixed.length} rows, to_precision: ${precision.length} rows`);
